    // The cast to a type specified by a type parameter. Each comparison is a constant for a given TTo, so the JIT removes every other cast.
    internal static TTo? CastOrNull<TFrom, TTo>(TFrom self) where TFrom : IForm where TTo : struct
    {
        if (typeof(TTo) == typeof(TFrom)) { return Unsafe.As<TFrom, TTo>(ref self); }
        if (typeof(TTo) == typeof(Actor)) { Actor? cast = Actor.OrNull(NativeBindings.SF_Cast_Actor(self.Address)); return Unsafe.As<Actor?, TTo?>(ref cast); }
